#!/usr/bin/env bash
# Start host services and bootstrap Gitea (admin user, API token, Actions runner token). Idempotent.
# Usage: lab services up [--gpu]
source "$(dirname "$0")/../lib/common.sh"
need curl jq

profiles=()
if [[ ${1:-} == --gpu ]]; then profiles=(--profile gpu); fi

ensure_secrets_dir
[[ -s $SECRETS_DIR/gitea-db-password ]] || randpw >"$SECRETS_DIR/gitea-db-password"

cd "$LAB_ROOT/services"
umask 077
cat >.env <<EOF
# generated by services/up.sh — do not edit, change config.env instead
GITEA_DB_PASSWORD=$(<"$SECRETS_DIR/gitea-db-password")
GITEA_IMAGE=$GITEA_IMAGE
LAB_DOMAIN=$LAB_DOMAIN
LAB_GW_IP=$LAB_GW_IP
GITEA_HTTP_PORT=$GITEA_HTTP_PORT
GITEA_SSH_PORT=$GITEA_SSH_PORT
REGISTRY_PORT=$REGISTRY_PORT
OLLAMA_PORT=$OLLAMA_PORT
EOF
umask 022

log "Starting services"
dk compose "${profiles[@]}" up -d

log "Waiting for Gitea"
for _ in $(seq 1 90); do
  curl -fsS "$GITEA_API_URL/api/healthz" >/dev/null 2>&1 && break
  sleep 2
done
curl -fsS "$GITEA_API_URL/api/healthz" >/dev/null || die "Gitea is not healthy; check: lab services logs gitea"

gexec() { dk compose exec -T -u git gitea gitea "$@"; }

if ! gexec admin user list --admin | awk 'NR>1 {print $2}' | grep -qx "$GITEA_ADMIN_USER"; then
  log "Creating Gitea admin '$GITEA_ADMIN_USER'"
  randpw >"$SECRETS_DIR/gitea-admin-password"
  gexec admin user create --admin --username "$GITEA_ADMIN_USER" --email "$GITEA_ADMIN_EMAIL" \
    --password "$(<"$SECRETS_DIR/gitea-admin-password")" --must-change-password=false >/dev/null
fi

if [[ ! -s $SECRETS_DIR/gitea-admin-token ]]; then
  log "Creating admin API token"
  gexec admin user generate-access-token --username "$GITEA_ADMIN_USER" \
    --token-name "agentlab-$(date +%Y%m%d%H%M%S)" --scopes all --raw | tail -n1 | tr -d '\r\n' \
    >"$SECRETS_DIR/gitea-admin-token"
fi

if [[ ! -s $SECRETS_DIR/runner-token ]]; then
  log "Creating Actions runner registration token"
  gexec actions generate-runner-token | tail -n1 | tr -d '\r\n' >"$SECRETS_DIR/runner-token"
fi

# Your host SSH key on the admin account, so you can clone/review from the host.
if [[ -f $SSH_PUBKEY_FILE ]]; then
  key=$(awk '{print $1" "$2}' "$SSH_PUBKEY_FILE")
  if ! gitea_api GET "/users/$GITEA_ADMIN_USER/keys" \
      | jq -e --arg k "$key" 'any(.[]; (.key | split(" ")[0:2] | join(" ")) == $k)' >/dev/null; then
    log "Adding $SSH_PUBKEY_FILE to $GITEA_ADMIN_USER"
    gitea_api POST "/admin/users/$GITEA_ADMIN_USER/keys" \
      "$(jq -n --arg k "$key" --arg t "host-$(hostname)" '{title:$t, key:$k, read_only:false}')" >/dev/null
  fi
fi

cat <<EOF

Gitea:     http://gitea.$LAB_DOMAIN:$GITEA_HTTP_PORT   (from host and VMs)
Admin:     $GITEA_ADMIN_USER / password in $SECRETS_DIR/gitea-admin-password
Clone:     git clone ssh://git@gitea.$LAB_DOMAIN:$GITEA_SSH_PORT/<org>/<repo>.git
Registry:  $LAB_GW_IP:$REGISTRY_PORT (Docker Hub mirror, used by VMs)
EOF
